package sfz.nosql.l04.demo

import software.amazon.awssdk.services.dynamodb.model.QueryResponse

/** One item collection holds an account, its payments, refunds and ledger. Which Query returns the account screen? */
fun main() {
    val ddb = localClient()
    val table = "demo-single"
    createPaymentsTable(ddb, table)
    seedPayments(ddb, table) // 12 items, written in no particular order (see DemoTable.kt)

    fun show(title: String, r: QueryResponse) {
        println("$title  (read ${r.scannedCount()}, returned ${r.count()})")
        r.items().forEach { println("  %-44s %s".format(it["sk"]!!.s(), it["type"]!!.s())) }
    }

    // 1. the whole item collection: DynamoDB keeps it sorted by sk, byte by byte
    show("pk = ACCT#A-1001, forward:", ddb.query {
        it.tableName(table)
            .keyConditionExpression("pk = :pk")
            .expressionAttributeValues(mapOf(":pk" to s("ACCT#A-1001")))
    })

    // 2. backward from the end, 4 items: the refunds sort last, so they come first
    show("backward, Limit 4, no condition on sk:", ddb.query {
        it.tableName(table)
            .keyConditionExpression("pk = :pk")
            .expressionAttributeValues(mapOf(":pk" to s("ACCT#A-1001")))
            .scanIndexForward(false).limit(4)
    })

    // 3. the account screen: only the run from PAY# to PROFILE, backward: profile, then newest payments
    show("backward, sk BETWEEN PAY# AND PROFILE, Limit 4:", ddb.query {
        it.tableName(table)
            .keyConditionExpression("pk = :pk AND sk BETWEEN :first AND :last")
            .expressionAttributeValues(mapOf(":pk" to s("ACCT#A-1001"), ":first" to s("PAY#"), ":last" to s("PROFILE")))
            .scanIndexForward(false).limit(4)
    })
    ddb.close()
}

package sfz.nosql.l04.demo

import software.amazon.awssdk.services.dynamodb.model.DynamoDbException

/** The same items, read through two global secondary indexes. */
fun main() {
    val ddb = localClient()
    val table = "demo-single"
    createPaymentsTable(ddb, table)
    seedPayments(ddb, table)

    // AP2 + AP6: byPayment is keyed (paymentId; sk), so the payment and its refunds sit together
    println("byPayment, paymentId = pay-81723:")
    ddb.query {
        it.tableName(table).indexName("byPayment")
            .keyConditionExpression("paymentId = :id")
            .expressionAttributeValues(mapOf(":id" to s("pay-81723")))
    }.items().forEach { println("  %-8s %s".format(it["type"]!!.s(), it["sk"]!!.s())) }

    // AP3: byMerchant is keyed (merchantId; status, createdAt): = on status, then a range on createdAt
    println("byMerchant, M-0042, FAILED, 09:00 to 12:00, newest first:")
    ddb.query {
        it.tableName(table).indexName("byMerchant")
            .keyConditionExpression("merchantId = :m AND #status = :st AND createdAt BETWEEN :from AND :to")
            .expressionAttributeNames(mapOf("#status" to "status")) // status is a reserved word
            .expressionAttributeValues(mapOf(
                ":m" to s("M-0042"), ":st" to s("FAILED"),
                ":from" to s("2026-11-07T09:00:00.000Z"), ":to" to s("2026-11-07T12:00:00.000Z"),
            ))
            .scanIndexForward(false)
    }.items().forEach { println("  %s  %s  %s  %s".format(it["createdAt"]!!.s(), it["paymentId"]!!.s(), it["accountId"]!!.s(), it["amountMinor"]!!.n())) }

    // the same, but skip status: the sort key is used left to right, with no gaps
    try {
        ddb.query {
            it.tableName(table).indexName("byMerchant")
                .keyConditionExpression("merchantId = :m AND createdAt > :from")
                .expressionAttributeValues(mapOf(":m" to s("M-0042"), ":from" to s("2026-11-07T09:00:00.000Z")))
        }
    } catch (e: DynamoDbException) {
        println("skip status: ${e.awsErrorDetails().errorMessage()}")
    }

    // an item is in an index only if it has the index's key attributes
    fun count(index: String?) = ddb.scan { r -> r.tableName(table).apply { if (index != null) indexName(index) } }.count()
    println("items: table ${count(null)}, byPayment ${count("byPayment")}, byMerchant ${count("byMerchant")}")
    ddb.close()
}

package sfz.nosql.l04.demo

import software.amazon.awssdk.services.dynamodb.model.Put
import software.amazon.awssdk.services.dynamodb.model.TransactWriteItem
import software.amazon.awssdk.services.dynamodb.model.TransactionCanceledException
import software.amazon.awssdk.services.dynamodb.model.Update

/** A transfer as one TransactWriteItems: it all happens, or none of it does. */
fun main() {
    val ddb = localClient()
    val table = "demo-single"
    createPaymentsTable(ddb, table)
    seedPayments(ddb, table) // A-1001 holds 100.00 EUR, A-2002 holds 50.00 EUR

    fun balances() = listOf("A-1001", "A-2002").joinToString(", ") { acct ->
        val item = ddb.getItem { it.tableName(table).key(mapOf("pk" to s("ACCT#$acct"), "sk" to s("PROFILE"))).consistentRead(true) }.item()
        "$acct ${item["balanceMinor"]!!.n()}"
    }
    fun ledgerCount() = ddb.query {
        it.tableName(table).keyConditionExpression("pk = :pk AND begins_with(sk, :l)")
            .expressionAttributeValues(mapOf(":pk" to s("ACCT#A-1001"), ":l" to s("LEDGER#"))).consistentRead(true)
    }.count()

    fun attempt(label: String, key: String, amount: Long) {
        try {
            ddb.transactWriteItems { it.transactItems(transferActions(table, key, "txf-$key", "A-1001", "A-2002", amount)) }
            println("$label: committed")
        } catch (e: TransactionCanceledException) {
            println("$label: ${e.javaClass.simpleName}")
            // one reason per action, in the order they were sent
            val names = listOf("debit A-1001", "credit A-2002", "ledger A-1001", "ledger A-2002", "claim")
            e.cancellationReasons().forEachIndexed { i, r -> println("  [$i] %-14s %s".format(names[i], r.code())) }
        }
        println("  balances: ${balances()}; A-1001 ledger entries: ${ledgerCount()}")
    }

    println("before: ${balances()}; A-1001 ledger entries: ${ledgerCount()}")
    attempt("transfer 30.00 with key k-1", "k-1", 3_000)
    attempt("transfer 500.00 with key k-2", "k-2", 50_000)
    attempt("retry of k-1", "k-1", 3_000)
    ddb.close()
}

/** Debit, credit, two ledger entries and the idempotency claim: five actions, one request. */
fun transferActions(table: String, key: String, transferId: String, from: String, to: String, amount: Long): List<TransactWriteItem> {
    val amt = mapOf(":amt" to n(amount))
    fun ledger(account: String, signed: Long) = TransactWriteItem.builder().put(Put.builder().tableName(table).item(mapOf(
        "pk" to s("ACCT#$account"), "sk" to s("LEDGER#2026-11-07T12:30:00.000Z#$transferId"), "type" to s("LEDGER"),
        "transferId" to s(transferId), "amountMinor" to n(signed),
    )).build()).build()
    return listOf(
        TransactWriteItem.builder().update(Update.builder().tableName(table)
            .key(mapOf("pk" to s("ACCT#$from"), "sk" to s("PROFILE")))
            .updateExpression("SET balanceMinor = balanceMinor - :amt")
            .conditionExpression("balanceMinor >= :amt")      // no overdraft
            .expressionAttributeValues(amt).build()).build(),
        TransactWriteItem.builder().update(Update.builder().tableName(table)
            .key(mapOf("pk" to s("ACCT#$to"), "sk" to s("PROFILE")))
            .updateExpression("SET balanceMinor = balanceMinor + :amt")
            .conditionExpression("attribute_exists(pk)")       // the target account must exist
            .expressionAttributeValues(amt).build()).build(),
        ledger(from, -amount),
        ledger(to, amount),
        TransactWriteItem.builder().put(Put.builder().tableName(table)
            .item(mapOf("pk" to s("IDEMP#$key"), "sk" to s("IDEMP"), "type" to s("CLAIM"), "transferId" to s(transferId)))
            .conditionExpression("attribute_not_exists(pk)")   // first use of this key only
            .build()).build(),
    )
}

package sfz.nosql.l04.demo

import software.amazon.awssdk.services.dynamodb.model.IdempotentParameterMismatchException
import java.util.UUID

/** The request-level guard: a ClientRequestToken makes a repeated TransactWriteItems a no-op for 10 minutes. */
fun main() {
    val ddb = localClient()
    val table = "demo-single"
    createPaymentsTable(ddb, table)
    seedPayments(ddb, table) // A-1001 holds 100.00 EUR, A-2002 holds 50.00 EUR

    fun balance() = ddb.getItem {
        it.tableName(table).key(mapOf("pk" to s("ACCT#A-1001"), "sk" to s("PROFILE"))).consistentRead(true)
    }.item()["balanceMinor"]!!.n()

    // at most 36 characters; a fresh one per run, because DynamoDB remembers a token
    // for 10 minutes after the request that used it finishes
    val token = UUID.randomUUID().toString()
    fun send(key: String, amount: Long) = ddb.transactWriteItems {
        it.transactItems(transferActions(table, key, "txf-$key", "A-1001", "A-2002", amount))
            .clientRequestToken(token)
    }

    send("k-7", 3_000)
    println("first call with the token:        A-1001 = ${balance()}")
    send("k-7", 3_000) // say the response was lost and the caller sends the identical request again
    println("same request, same token again:   A-1001 = ${balance()}  (success, nothing written)")
    try {
        send("k-7", 4_000)
    } catch (e: IdempotentParameterMismatchException) {
        println("same token, amount 40.00:         ${e.javaClass.simpleName}")
    }
    ddb.close()
}

